return {
  heal: {
    hook: "onAttackResult",
    timing: "afterDamageApplied",
    damageType: "Wounds",
    active(H, actor, ctx) { return ctx.weapon?.id === ctx.item.id; },
    async run(H, actor) {
      await H.resource.adjust(actor, { wounds: 1 });
      await H.chat.post("Wicked: heal 1 Wound.", actor);
    },
  },
};
